import type { Html } from "foldkit/html";
import { html } from "foldkit/html";

import {
  inputOtpGroupClassName,
  inputOtpRootClassName,
  inputOtpSeparatorClassName,
  inputOtpSlotClassName,
} from "./view";

export {
  inputOtpGroupClassName,
  inputOtpRootClassName,
  inputOtpSeparatorClassName,
  inputOtpSlotClassName,
} from "./view";

export type ViewConfig = Readonly<{
  children: readonly Html[];
  className?: string | undefined;
}>;

export type SlotViewConfig<ParentMessage> = Readonly<{
  id?: string | undefined;
  value: string;
  ariaLabel: string;
  onInput: (value: string) => ParentMessage;
  inputMode?: string | undefined;
  pattern?: string | undefined;
  active?: boolean | undefined;
  className?: string | undefined;
}>;

const classNames = (base: string, className?: string): string =>
  [base, className]
    .filter((value): value is string => value !== undefined && value !== "")
    .join(" ");

export const rootView = <ParentMessage>({
  children,
  className,
}: ViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      h.DataAttribute("slot", "input-otp"),
      h.Class(classNames(inputOtpRootClassName, className)),
    ],
    children
  );
};

export const groupView = <ParentMessage>({
  children,
  className,
}: ViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      h.DataAttribute("slot", "input-otp-group"),
      h.Class(classNames(inputOtpGroupClassName, className)),
    ],
    children
  );
};

export const slotView = <ParentMessage>({
  id,
  value,
  ariaLabel,
  onInput,
  inputMode,
  pattern,
  active = false,
  className,
}: SlotViewConfig<ParentMessage>): Html => {
  const h = html<ParentMessage>();

  return h.input([
    ...(id === undefined ? [] : [h.Id(id)]),
    h.Type("text"),
    h.Value(value),
    h.AriaLabel(ariaLabel),
    h.Autocomplete("one-time-code"),
    h.Attribute("maxlength", "1"),
    h.OnInput(onInput),
    ...(inputMode === undefined ? [] : [h.Attribute("inputmode", inputMode)]),
    ...(pattern === undefined ? [] : [h.Attribute("pattern", pattern)]),
    h.DataAttribute("slot", "input-otp-slot"),
    h.DataAttribute("active", active ? "true" : "false"),
    h.DataAttribute("filled", value === "" ? "false" : "true"),
    h.Class(classNames(inputOtpSlotClassName, className)),
  ]);
};

export const separatorView = <ParentMessage>(): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      h.AriaHidden(true),
      h.DataAttribute("slot", "input-otp-separator"),
      h.Class(inputOtpSeparatorClassName),
    ],
    ["•"]
  );
};

export const inputOtpRootClassName = "flex items-center gap-2";
export const inputOtpGroupClassName = "flex items-center";
export const inputOtpSlotClassName =
  "relative flex h-10 w-10 items-center justify-center border-y border-r border-gray-300 bg-white text-center text-sm text-gray-950 shadow-sm outline-none transition-all first:rounded-l-md first:border-l last:rounded-r-md focus:z-10 focus:border-gray-950 focus:ring-2 focus:ring-gray-950 focus:ring-offset-2 data-[active=true]:z-10 data-[active=true]:border-gray-950 data-[active=true]:ring-2 data-[active=true]:ring-gray-950 data-[active=true]:ring-offset-2";
export const inputOtpSeparatorClassName =
  "mx-2 flex h-10 items-center text-gray-950";

import { Scene } from "foldkit";
import type { Html } from "foldkit/html";
import { describe, test } from "vitest";

import * as InputOtp from "./index";

const view = (digit: string): Html =>
  InputOtp.rootView<string>({
    children: [
      InputOtp.groupView<string>({
        children: [
          InputOtp.slotView<string>({
            value: digit,
            ariaLabel: "Digit 1",
            onInput: (value) => value,
            active: true,
          }),
        ],
      }),
      InputOtp.separatorView<string>(),
    ],
  });

describe("Input OTP registry view", () => {
  test("renders one-time-code slot state", () => {
    Scene.scene(
      {
        update: (_model: string, message: string): readonly [string, []] => [
          message,
          [],
        ],
        view,
      },
      Scene.with(""),
      Scene.expect(Scene.role("textbox", { name: "Digit 1" })).toHaveAttr(
        "autocomplete",
        "one-time-code"
      ),
      Scene.type(Scene.role("textbox", { name: "Digit 1" }), "4"),
      Scene.expect(Scene.role("textbox", { name: "Digit 1" })).toHaveValue("4")
    );
  });
});
